```typescript
import { env } from "zttp:env";
import { parseBearer, jwtVerify } from "zttp:auth";

function handler(req: Request): Proof<Response, "read_only" | "retry_safe" | "state_isolated" | "fault_covered" | "stateless" | "result_safe" | "optional_safe" | "input_validated" | "pii_contained" | "injection_safe" | "canonical" | "cost_bounded"> {
    const token = parseBearer(req.headers["authorization"]);
    if (token === undefined) {
        return Response.json({ error: "unauthorized" }, { status: 401 });
    }
    const secret = env("JWT_SECRET");
    if (secret === undefined) {
        return Response.json({ error: "server misconfigured" }, { status: 500 });
    }
    const verified = jwtVerify(token, secret);
    if (!verified.ok) {
        return Response.json({ error: "unauthorized" }, { status: 401 });
    }
    return Response.json(verified.value);
}
```

Wait — but the `Proof<T, P>` usage from the meta: `structural Guard<T> = Proof<T, "state_isolated">;` and handlers return `Guard<Response>`. Direct `Proof<Response, "read_only" | ...>` — is that valid syntax? The ZTS500 suggestion literally says `function handler(req: Request): Proof<Response, "read_only" | ...>` so yes, direct is fine.

Also, is the Proof union type accepted inline? Per the suggestion, yes.

Should I use `export`? The meta examples use `export function handler`. The ZTS500 diagnostic pointed at line 4 column 24 (the `)` of the return type, i.e., the missing Proof). No complaint about export. Keep `export`.

